safe_remediated_config:
# [REMEDIATED] Scoped AWS Security Group Egress Rule
resource "aws_security_group_rule" "remediated_outbound_egress" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["198.51.100.0/24"] # Scoped partner CIDR (RFC 5737)
  security_group_id = "sg-analytics-web-01"
}

# [REMEDIATED] Scoped Least-Privilege IAM Policy for Telemetry Ingestion
resource "aws_iam_policy" "scoped_telemetry_s3_write" {
  name        = "pol-telemetry-staging-write-only"
  description = "Scoped write-only access to unclassified telemetry bucket"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action   = ["s3:PutObject", "s3:AbortMultipartUpload"]
      Effect   = "Allow"
      Resource = "arn:aws:s3:::apex-telemetry-staging-us-east-1/*"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "scoped_analytics_attachment" {
  role       = "role-analytics-ingestion-svc"
  policy_arn = aws_iam_policy.scoped_telemetry_s3_write.arn
}
